/**
 * SISOMA API — Export Module v3.0
 * PDF Institucional con logos oficiales + envío por correo
 * Válido para auditorías STPS / SEMARNAT / Protección Civil
 */
import jsPDF from 'jspdf'
import autoTable from 'jspdf-autotable'
import * as XLSX from 'xlsx'

// ─── Logos institucionales (base64) ────────────────────────────────────────
const LOGO_SSOMA     = "data:image/jpeg;base64,"
const LOGO_FIBERHOME = "data:image/jpeg;base64,"
const LOGO_HOMETEX   = "data:image/jpeg;base64,"
const LOGO_COLCHAS   = "data:image/jpeg;base64,"

// ─── Colores institucionales ────────────────────────────────────────────────
const C = {
  purple:  [124, 58,  237],
  dark:    [11,  7,   24],
  gray:    [100, 100, 100],
  light:   [245, 243, 255],
  white:   [255, 255, 255],
  border:  [200, 195, 220],
  blue:    [37,  99,  235],
  green:   [16,  185, 129],
  red:     [239, 68,  68],
}

// ─── Helpers ────────────────────────────────────────────────────────────────
function getEmpresaLogos(empresa) {
  if (!empresa) return [LOGO_FIBERHOME]
  const e = empresa.toLowerCase()
  if (e.includes('fiber'))   return [LOGO_FIBERHOME]
  if (e.includes('hometex')) return [LOGO_HOMETEX]
  if (e.includes('colchas')) return [LOGO_COLCHAS]
  return [LOGO_FIBERHOME]
}

function getNOMReference(category) {
  const map = {
    'Seguridad Industrial': 'NOM-030-STPS-2009 · NOM-017-STPS-2008',
    'Salud Ocupacional':    'NOM-030-STPS-2009 · NOM-010-STPS-2014',
    'Medio Ambiente':       'NOM-018-STPS-2015 · LGEEPA',
    'Protección Civil':     'NOM-002-STPS-2010 · NOM-003-SEGOB-2011',
    'General':              'NOM-030-STPS-2009',
  }
  return map[category] || 'NOM-030-STPS-2009'
}

// ─── Encabezado institucional ───────────────────────────────────────────────
function addInstitutionalHeader(doc, response) {
  const W = doc.internal.pageSize.getWidth()

  // Banda superior morada
  doc.setFillColor(...C.purple)
  doc.rect(0, 0, W, 32, 'F')

  // Línea dorada decorativa
  doc.setFillColor(212, 175, 55)
  doc.rect(0, 32, W, 1.5, 'F')

  // Logo SSOMA (izquierda)
  try { doc.addImage(LOGO_SSOMA, 'JPEG', 6, 2, 27, 27) } catch(e) {}

  // Título central en banda morada
  doc.setTextColor(...C.white)
  doc.setFontSize(13)
  doc.setFont('helvetica', 'bold')
  doc.text('SISTEMA INTEGRAL SSOMA', W/2, 13, { align: 'center' })
  doc.setFontSize(8)
  doc.setFont('helvetica', 'normal')
  doc.text('Seguridad · Salud Ocupacional · Medio Ambiente', W/2, 20, { align: 'center' })
  doc.text('Complejo Industrial Concord', W/2, 27, { align: 'center' })

  // Logos empresa (derecha en banda morada)
  const empresaLogo = getEmpresaLogos(response.empresa)[0]
  try {
    doc.setFillColor(...C.white)
    doc.roundedRect(W - 38, 3, 34, 26, 2, 2, 'F')
    doc.addImage(empresaLogo, 'JPEG', W - 36, 5, 30, 22)
  } catch(e) {}

  // Segunda fila: datos del documento
  doc.setFillColor(...C.light)
  doc.rect(0, 33.5, W, 18, 'F')
  doc.setDrawColor(...C.border)
  doc.rect(0, 33.5, W, 18, 'S')

  doc.setTextColor(...C.dark)
  doc.setFontSize(9)
  doc.setFont('helvetica', 'bold')
  // Título del formulario
  const title = response.form_name || 'Formulario SSOMA'
  doc.text(title.toUpperCase(), 8, 42)

  doc.setFontSize(7.5)
  doc.setFont('helvetica', 'normal')
  doc.setTextColor(...C.gray)
  doc.text(getNOMReference(response.category || 'Seguridad Industrial'), 8, 48)

  // Folio + fecha (derecha)
  doc.setTextColor(...C.purple)
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(8.5)
  doc.text(`Folio: ${response.id}`, W - 8, 40, { align: 'right' })
  doc.setTextColor(...C.gray)
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(7.5)
  const fecha = new Date(response.submitted_at).toLocaleString('es-MX', {
    weekday:'long', year:'numeric', month:'long', day:'numeric',
    hour:'2-digit', minute:'2-digit'
  })
  doc.text(fecha, W - 8, 46, { align: 'right' })
  doc.text(`Estado: ${(response.status||'COMPLETO').toUpperCase()}`, W - 8, 51, { align: 'right' })

  return 58 // Y position after header
}

// ─── Sección de datos del usuario ──────────────────────────────────────────
function addUserSection(doc, response, y) {
  const W = doc.internal.pageSize.getWidth()

  doc.setFillColor(37, 19, 89)
  doc.roundedRect(8, y, W - 16, 6, 1, 1, 'F')
  doc.setTextColor(...C.white)
  doc.setFontSize(8)
  doc.setFont('helvetica', 'bold')
  doc.text('  DATOS DEL TRABAJADOR RESPONSABLE', 8, y + 4.5)
  y += 8

  const fields = [
    ['Nombre completo:', response.user_name || '—'],
    ['No. de empleado:', response.user_emp  || '—'],
    ['Área / Depto.:',   response.user_area || '—'],
    ['Empresa:',         response.empresa   || '—'],
  ]
  const col = (W - 16) / 2
  doc.setFillColor(250, 248, 255)
  doc.roundedRect(8, y, W - 16, 18, 1, 1, 'F')
  doc.setDrawColor(...C.border)
  doc.roundedRect(8, y, W - 16, 18, 1, 1, 'S')

  fields.forEach(([k, v], i) => {
    const x = 8 + (i % 2) * col + 3
    const yi = y + 5 + Math.floor(i / 2) * 8
    doc.setTextColor(...C.gray)
    doc.setFontSize(7)
    doc.setFont('helvetica', 'normal')
    doc.text(k, x, yi)
    doc.setTextColor(...C.dark)
    doc.setFontSize(8)
    doc.setFont('helvetica', 'bold')
    doc.text(v, x + 28, yi)
  })

  // Score badge
  if (response.score) {
    const scoreColor = response.score >= 70 ? C.green : C.red
    doc.setFillColor(...scoreColor)
    doc.roundedRect(W - 30, y + 2, 22, 14, 2, 2, 'F')
    doc.setTextColor(...C.white)
    doc.setFontSize(14)
    doc.setFont('helvetica', 'bold')
    doc.text(`${response.score}%`, W - 19, y + 12, { align: 'center' })
    doc.setFontSize(6)
    doc.setFont('helvetica', 'normal')
    doc.text('CALIFIC.', W - 19, y + 16.5, { align: 'center' })
  }

  return y + 22
}

// ─── Pie de página ──────────────────────────────────────────────────────────
function addFooters(doc, response) {
  const pages = doc.internal.getNumberOfPages()
  const W = doc.internal.pageSize.getWidth()
  const H = doc.internal.pageSize.getHeight()

  for (let i = 1; i <= pages; i++) {
    doc.setPage(i)

    // Banda inferior
    doc.setFillColor(...C.light)
    doc.rect(0, H - 20, W, 20, 'F')
    doc.setDrawColor(...C.border)
    doc.line(0, H - 20, W, H - 20)

    // Logos de las 3 empresas en el footer
    const footerLogos = [
      { img: LOGO_FIBERHOME, x: 8   },
      { img: LOGO_HOMETEX,   x: 40  },
      { img: LOGO_COLCHAS,   x: 72  },
    ]
    footerLogos.forEach(l => {
      try {
        doc.setFillColor(...C.white)
        doc.roundedRect(l.x, H - 18, 28, 15, 1, 1, 'F')
        doc.addImage(l.img, 'JPEG', l.x + 1, H - 17, 26, 13)
      } catch(e) {}
    })

    // SSOMA logo pequeño
    try { doc.addImage(LOGO_SSOMA, 'JPEG', 104, H - 18, 13, 13) } catch(e) {}

    // Texto central
    doc.setTextColor(...C.gray)
    doc.setFontSize(6.5)
    doc.setFont('helvetica', 'normal')
    doc.text('Documento generado por SISOMA API — Sistema Integral SSOMA', W/2, H - 13, { align: 'center' })
    doc.text(`Folio: ${response.id} · ${getNOMReference(response.category || '')}`, W/2, H - 8, { align: 'center' })
    doc.text(`Este documento tiene validez legal como registro de verificación conforme a la Ley Federal del Trabajo`, W/2, H - 4, { align: 'center' })

    // Número de página
    doc.setFillColor(...C.purple)
    doc.roundedRect(W - 24, H - 16, 16, 10, 2, 2, 'F')
    doc.setTextColor(...C.white)
    doc.setFontSize(7)
    doc.setFont('helvetica', 'bold')
    doc.text(`${i}/${pages}`, W - 16, H - 9.5, { align: 'center' })

    // Sello SISOMA API (esquina superior derecha de cada página excepto la 1)
    if (i > 1) {
      doc.setTextColor(200, 190, 230)
      doc.setFontSize(6)
      doc.setFont('helvetica', 'normal')
      doc.text(`SISOMA API · ${response.id}`, W - 8, 8, { align: 'right' })
    }
  }
}

// ─── Sello de validez ───────────────────────────────────────────────────────
function addValiditySeal(doc, response, y) {
  const W = doc.internal.pageSize.getWidth()

  doc.setDrawColor(...C.purple)
  doc.setLineWidth(0.8)
  doc.roundedRect(8, y, W - 16, 20, 2, 2, 'S')
  doc.setFillColor(248, 246, 255)
  doc.roundedRect(8, y, W - 16, 20, 2, 2, 'F')
  doc.setDrawColor(...C.purple)
  doc.roundedRect(8, y, W - 16, 20, 2, 2, 'S')

  try { doc.addImage(LOGO_SSOMA, 'JPEG', 12, y + 2, 14, 14) } catch(e) {}

  doc.setTextColor(...C.purple)
  doc.setFontSize(8)
  doc.setFont('helvetica', 'bold')
  doc.text('✓  DOCUMENTO GENERADO POR SISOMA API', 30, y + 8)
  doc.setTextColor(...C.gray)
  doc.setFontSize(7)
  doc.setFont('helvetica', 'normal')
  doc.text(`Folio: ${response.id} · Registrado: ${new Date(response.submitted_at).toLocaleString('es-MX')}`, 30, y + 14)
  doc.text(`Usuario: ${response.user_name} (${response.user_emp}) · Empresa: ${response.empresa}`, 30, y + 18.5)

  return y + 24
}

// ═══════════════════════════════════════════════════════════════════════════
// EXPORTACIÓN PRINCIPAL — PDF Institucional
// ═══════════════════════════════════════════════════════════════════════════
export function exportResponsePDF(response) {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })
  const W   = doc.internal.pageSize.getWidth()

  let y = addInstitutionalHeader(doc, response)
  y     = addUserSection(doc, response, y)
  y    += 4

  // ─── Respuestas ───────────────────────────────────────────────────────
  if (response.answers?.length) {
    // Separar respuestas normales, fotos y firmas
    const normalAnswers = response.answers.filter(a => a.question_type !== 'sign' && a.question_type !== 'photo')
    const signAnswers   = response.answers.filter(a => a.question_type === 'sign')
    const photoAnswers  = response.answers.filter(a => a.question_type === 'photo' && a.value?.data)

    // Título sección respuestas
    doc.setFillColor(37, 19, 89)
    doc.roundedRect(8, y, W - 16, 6, 1, 1, 'F')
    doc.setTextColor(...C.white)
    doc.setFontSize(8)
    doc.setFont('helvetica', 'bold')
    doc.text(`  RESPUESTAS DEL FORMULARIO (${response.answers.length} preguntas)`, 8, y + 4.5)
    y += 8

    // Tabla de respuestas
    const rows = normalAnswers.map((a, i) => {
      let val = a.value
      if (Array.isArray(val))                          val = val.join(', ')
      else if (typeof val === 'object' && val !== null) val = JSON.stringify(val)
      else if (a.question_type === 'sign')              val = '[Ver firma al final del documento]'
      else if (a.question_type === 'photo')             val = '[Ver fotografía al final del documento]'
      else                                              val = String(val ?? '—')
      return [i + 1, a.question_text || '—', val]
    })

    autoTable(doc, {
      startY: y,
      head:   [['#', 'Pregunta', 'Respuesta']],
      body:   rows,
      headStyles:          { fillColor: C.purple, textColor: 255, fontStyle:'bold', fontSize:8 },
      bodyStyles:          { fontSize:8, textColor:C.dark, cellPadding:3 },
      alternateRowStyles:  { fillColor:[248,246,255] },
      columnStyles:        { 0:{cellWidth:8}, 1:{cellWidth:85}, 2:{cellWidth:85} },
      margin:              { left:8, right:8 },
      styles:              { overflow:'linebreak', lineColor:C.border, lineWidth:0.2 },
      didDrawPage:         () => {},
    })
    y = doc.lastAutoTable.finalY + 6

    // ─── Firmas digitales ──────────────────────────────────────────────
    if (signAnswers.length) {
      if (y > 220) { doc.addPage(); y = 20 }

      doc.setFillColor(37, 19, 89)
      doc.roundedRect(8, y, W - 16, 6, 1, 1, 'F')
      doc.setTextColor(...C.white)
      doc.setFontSize(8)
      doc.setFont('helvetica', 'bold')
      doc.text('  FIRMAS DIGITALES CAPTURADAS', 8, y + 4.5)
      y += 10

      signAnswers.forEach((a, i) => {
        if (y > 240) { doc.addPage(); y = 20 }
        const boxW = (W - 20) / Math.min(signAnswers.length, 2)
        const x    = 8 + (i % 2) * (boxW + 4)
        if (i % 2 === 0 && i > 0) y += 40

        doc.setFillColor(250, 248, 255)
        doc.setDrawColor(...C.border)
        doc.roundedRect(x, y, boxW, 36, 2, 2, 'FD')

        doc.setTextColor(...C.gray)
        doc.setFontSize(7)
        doc.setFont('helvetica', 'normal')
        doc.text(a.question_text || `Firma ${i+1}`, x + 3, y + 5)

        if (a.value && typeof a.value === 'string' && a.value.startsWith('data:')) {
          try {
            doc.addImage(a.value, 'PNG', x + 5, y + 8, boxW - 10, 22)
          } catch(e) {
            doc.setTextColor(...C.purple)
            doc.setFontSize(8)
            doc.text('✓ Firma digital capturada', x + boxW/2, y + 20, { align:'center' })
          }
        } else {
          doc.setTextColor(...C.purple)
          doc.setFontSize(8)
          doc.text('✓ Firma digital capturada', x + boxW/2, y + 20, { align:'center' })
        }

        // Línea base de firma
        doc.setDrawColor(...C.border)
        doc.setLineWidth(0.3)
        doc.line(x + 5, y + 31, x + boxW - 5, y + 31)
        doc.setTextColor(...C.gray)
        doc.setFontSize(6.5)
        doc.text(response.user_name || '', x + boxW/2, y + 34.5, { align:'center' })

        if (i % 2 === 1 || i === signAnswers.length - 1) y += 38
      })
      y += 4
    }

    // ─── Fotografías ──────────────────────────────────────────────────
    if (photoAnswers.length) {
      if (y > 200) { doc.addPage(); y = 20 }

      doc.setFillColor(37, 19, 89)
      doc.roundedRect(8, y, W - 16, 6, 1, 1, 'F')
      doc.setTextColor(...C.white)
      doc.setFontSize(8)
      doc.setFont('helvetica', 'bold')
      doc.text('  EVIDENCIA FOTOGRÁFICA', 8, y + 4.5)
      y += 10

      photoAnswers.forEach((a, i) => {
        if (y > 200) { doc.addPage(); y = 20 }
        const imgW = (W - 24) / 2
        const x    = 8 + (i % 2) * (imgW + 4)
        if (i % 2 === 0 && i > 0) y += imgW * 0.75 + 14

        doc.setFillColor(250, 248, 255)
        doc.setDrawColor(...C.border)
        doc.roundedRect(x, y, imgW, imgW * 0.75 + 12, 2, 2, 'FD')

        doc.setTextColor(...C.gray)
        doc.setFontSize(7)
        doc.text(a.question_text?.slice(0, 40) || `Foto ${i+1}`, x + 3, y + 5)

        try {
          doc.addImage(a.value.data, 'JPEG', x + 3, y + 8, imgW - 6, imgW * 0.75 - 2)
        } catch(e) {
          doc.setTextColor(180, 180, 180)
          doc.setFontSize(8)
          doc.text('📷 Imagen adjunta', x + imgW/2, y + imgW*0.375 + 8, { align:'center' })
        }

        if (i % 2 === 1 || i === photoAnswers.length - 1) y += imgW * 0.75 + 14
      })
      y += 4
    }
  }

  // ─── Sello de validez ───────────────────────────────────────────────
  if (y > 240) { doc.addPage(); y = 20 }
  addValiditySeal(doc, response, y)

  // ─── Pies de página en todas las hojas ──────────────────────────────
  addFooters(doc, response)

  doc.save(`SISOMA_${response.id}_${(response.form_name||'').replace(/[^a-zA-Z0-9]/g,'_').slice(0,30)}.pdf`)
}

// ─── Retorna el PDF como base64 (para envío por email) ─────────────────────
export function getResponsePDFBase64(response) {
  const doc = new jsPDF({ orientation:'portrait', unit:'mm', format:'a4' })
  const W   = doc.internal.pageSize.getWidth()

  let y = addInstitutionalHeader(doc, response)
  y     = addUserSection(doc, response, y)
  y    += 4

  if (response.answers?.length) {
    const normalAnswers = response.answers.filter(a => a.question_type !== 'sign' && a.question_type !== 'photo')
    const signAnswers   = response.answers.filter(a => a.question_type === 'sign')
    const photoAnswers  = response.answers.filter(a => a.question_type === 'photo' && a.value?.data)

    doc.setFillColor(37, 19, 89)
    doc.roundedRect(8, y, W - 16, 6, 1, 1, 'F')
    doc.setTextColor(255,255,255)
    doc.setFontSize(8)
    doc.setFont('helvetica','bold')
    doc.text(`  RESPUESTAS (${response.answers.length} preguntas)`, 8, y + 4.5)
    y += 8

    const rows = normalAnswers.map((a, i) => {
      let val = a.value
      if (Array.isArray(val)) val = val.join(', ')
      else if (typeof val === 'object' && val !== null) val = JSON.stringify(val)
      else val = String(val ?? '—')
      return [i + 1, a.question_text || '—', val]
    })

    autoTable(doc, {
      startY:y, head:[['#','Pregunta','Respuesta']],
      body:rows,
      headStyles:{ fillColor:C.purple, textColor:255, fontStyle:'bold', fontSize:8 },
      bodyStyles:{ fontSize:8, textColor:C.dark, cellPadding:3 },
      alternateRowStyles:{ fillColor:[248,246,255] },
      columnStyles:{ 0:{cellWidth:8}, 1:{cellWidth:85}, 2:{cellWidth:85} },
      margin:{ left:8, right:8 },
      styles:{ overflow:'linebreak', lineColor:C.border, lineWidth:0.2 },
    })
    y = doc.lastAutoTable.finalY + 6

    if (signAnswers.length) {
      if (y > 220) { doc.addPage(); y = 20 }
      doc.setFillColor(37,19,89)
      doc.roundedRect(8,y,W-16,6,1,1,'F')
      doc.setTextColor(255,255,255)
      doc.setFontSize(8)
      doc.setFont('helvetica','bold')
      doc.text('  FIRMAS DIGITALES', 8, y+4.5)
      y += 10
      signAnswers.forEach((a,i) => {
        if (y>240){doc.addPage();y=20}
        const boxW=(W-20)/Math.min(signAnswers.length,2)
        const x=8+(i%2)*(boxW+4)
        if(i%2===0&&i>0) y+=40
        doc.setFillColor(250,248,255)
        doc.setDrawColor(...C.border)
        doc.roundedRect(x,y,boxW,36,2,2,'FD')
        doc.setTextColor(...C.gray)
        doc.setFontSize(7)
        doc.text(a.question_text||`Firma ${i+1}`,x+3,y+5)
        if(a.value&&typeof a.value==='string'&&a.value.startsWith('data:')){
          try{ doc.addImage(a.value,'PNG',x+5,y+8,boxW-10,22) }catch(e){
            doc.setTextColor(...C.purple);doc.setFontSize(8)
            doc.text('✓ Firma capturada',x+boxW/2,y+20,{align:'center'})
          }
        } else {
          doc.setTextColor(...C.purple);doc.setFontSize(8)
          doc.text('✓ Firma digital capturada',x+boxW/2,y+20,{align:'center'})
        }
        doc.setDrawColor(...C.border);doc.setLineWidth(0.3)
        doc.line(x+5,y+31,x+boxW-5,y+31)
        doc.setTextColor(...C.gray);doc.setFontSize(6.5)
        doc.text(response.user_name||'',x+boxW/2,y+34.5,{align:'center'})
        if(i%2===1||i===signAnswers.length-1) y+=38
      })
      y+=4
    }
  }

  if (y>240){doc.addPage();y=20}
  addValiditySeal(doc, response, y)
  addFooters(doc, response)

  return doc.output('datauristring').split(',')[1]
}

// ─── PDF Lista de respuestas ────────────────────────────────────────────────
export function exportResponsesListPDF(responses, title = 'Listado de Respuestas') {
  const doc = new jsPDF({ orientation:'landscape', unit:'mm', format:'a4' })
  const W   = doc.internal.pageSize.getWidth()

  // Header simple
  doc.setFillColor(...C.purple)
  doc.rect(0, 0, W, 22, 'F')
  try { doc.addImage(LOGO_SSOMA,'JPEG',5,2,17,17) } catch(e){}
  doc.setTextColor(255,255,255)
  doc.setFontSize(12); doc.setFont('helvetica','bold')
  doc.text('SISOMA API — ' + title, 27, 12)
  doc.setFontSize(8); doc.setFont('helvetica','normal')
  doc.text(`Total: ${responses.length} registros · ${new Date().toLocaleString('es-MX')}`, 27, 18)

  const rows = responses.map(r => [
    r.id,
    (r.form_name||'').slice(0,32),
    r.user_name, r.user_emp, r.user_area,
    r.empresa?.split(' ')[0]||'—',
    r.score ? r.score+'%' : '—',
    (r.status||'').toUpperCase(),
    new Date(r.submitted_at).toLocaleDateString('es-MX'),
  ])

  autoTable(doc, {
    startY:26,
    head:[['Folio','Formulario','Usuario','No.Emp.','Área','Empresa','Score','Estado','Fecha']],
    body:rows,
    headStyles:{ fillColor:C.purple, textColor:255, fontStyle:'bold', fontSize:8 },
    bodyStyles:{ fontSize:7.5, textColor:C.dark },
    alternateRowStyles:{ fillColor:[248,246,255] },
    margin:{ left:8, right:8 },
    styles:{ lineColor:C.border, lineWidth:0.2 },
  })

  const pages = doc.internal.getNumberOfPages()
  const H = doc.internal.pageSize.getHeight()
  for(let i=1;i<=pages;i++){
    doc.setPage(i)
    doc.setFillColor(...C.light)
    doc.rect(0,H-12,W,12,'F')
    doc.setTextColor(...C.gray);doc.setFontSize(6.5)
    doc.text('Documento generado por SISOMA API · Complejo Industrial Concord',W/2,H-7,{align:'center'})
    doc.text(`Página ${i}/${pages}`,W-10,H-7,{align:'right'})
  }

  doc.save(`SISOMA_Listado_${new Date().toLocaleDateString('es-MX').replace(/\//g,'-')}.pdf`)
}

// ─── PDF Analíticos ─────────────────────────────────────────────────────────
export function exportAnalyticsPDF(analytics, responses, forms) {
  const doc = new jsPDF({ orientation:'portrait', unit:'mm', format:'a4' })
  const W   = doc.internal.pageSize.getWidth()

  doc.setFillColor(...C.purple)
  doc.rect(0,0,W,28,'F')
  try { doc.addImage(LOGO_SSOMA,'JPEG',6,3,20,20) }catch(e){}
  doc.setTextColor(255,255,255)
  doc.setFontSize(13);doc.setFont('helvetica','bold')
  doc.text('REPORTE ANALÍTICO SSOMA',W/2,14,{align:'center'})
  doc.setFontSize(8);doc.setFont('helvetica','normal')
  doc.text(`Complejo Industrial Concord · ${new Date().toLocaleDateString('es-MX')}`,W/2,21,{align:'center'})

  let y = 34
  const kpis = [
    {l:'Respuestas totales',   v:String(analytics.totalResponses||0)},
    {l:'Formularios activos',  v:String(analytics.activeForms||0)},
    {l:'Calificación promedio',v:(analytics.avgScore||0)+'%'},
    {l:'Usuarios registrados', v:String(analytics.users||0)},
  ]
  kpis.forEach((k,i) => {
    const x=8+(i%2)*96; const yi=y+Math.floor(i/2)*20
    doc.setFillColor(248,246,255); doc.roundedRect(x,yi,90,16,2,2,'F')
    doc.setFillColor(...C.purple); doc.roundedRect(x,yi,3,16,1,1,'F')
    doc.setTextColor(...C.gray);doc.setFontSize(7);doc.setFont('helvetica','normal')
    doc.text(k.l,x+7,yi+6)
    doc.setTextColor(...C.dark);doc.setFontSize(13);doc.setFont('helvetica','bold')
    doc.text(k.v,x+7,yi+14)
  })
  y += 46

  autoTable(doc,{
    startY:y,
    head:[['Formulario','Categoría','Estado','Respuestas']],
    body:forms.slice(0,12).map(f=>[f.name,f.category,f.status?.toUpperCase(),String(responses.filter(r=>r.form_id==f.id).length||f.responses_count||0)]),
    headStyles:{fillColor:C.purple,textColor:255,fontStyle:'bold',fontSize:8},
    bodyStyles:{fontSize:8},
    alternateRowStyles:{fillColor:[248,246,255]},
    margin:{left:8,right:8},
    styles:{lineColor:C.border,lineWidth:0.2},
  })

  const pages=doc.internal.getNumberOfPages()
  const H=doc.internal.pageSize.getHeight()
  for(let i=1;i<=pages;i++){
    doc.setPage(i)
    doc.setFillColor(...C.light);doc.rect(0,H-10,W,10,'F')
    doc.setTextColor(...C.gray);doc.setFontSize(6)
    doc.text('SISOMA API · Complejo Industrial Concord',W/2,H-5,{align:'center'})
    doc.text(`${i}/${pages}`,W-10,H-5,{align:'right'})
  }

  doc.save(`SISOMA_Analíticos_${new Date().toLocaleDateString('es-MX').replace(/\//g,'-')}.pdf`)
}

// ─── Excel ──────────────────────────────────────────────────────────────────
export function exportResponsesExcel(responses, filename='SISOMA_Respuestas') {
  const wb = XLSX.utils.book_new()
  const summaryData = [
    ['SISOMA API — Listado de Respuestas'],
    [`Complejo Industrial Concord · Generado: ${new Date().toLocaleString('es-MX')}`],
    [],
    ['Folio','Formulario','Usuario','No. Empleado','Área','Empresa','Calificación','Estado','Fecha de envío'],
    ...responses.map(r=>[r.id,r.form_name,r.user_name,r.user_emp,r.user_area,r.empresa,r.score?r.score+'%':'—',r.status,new Date(r.submitted_at).toLocaleString('es-MX')])
  ]
  const ws = XLSX.utils.aoa_to_sheet(summaryData)
  ws['!cols']=[8,35,20,12,15,15,12,10,20].map(w=>({wch:w}))
  XLSX.utils.book_append_sheet(wb,ws,'Respuestas')

  const formCounts={}
  responses.forEach(r=>{formCounts[r.form_name]=(formCounts[r.form_name]||0)+1})
  const statsData=[
    ['SISOMA API — Estadísticas'],[],
    ['Formulario','Total','% del Total'],
    ...Object.entries(formCounts).map(([k,v])=>[k,v,((v/responses.length)*100).toFixed(1)+'%']),
    [],['Total',responses.length,'100%'],
  ]
  const ws2=XLSX.utils.aoa_to_sheet(statsData)
  ws2['!cols']=[35,12,12].map(w=>({wch:w}))
  XLSX.utils.book_append_sheet(wb,ws2,'Estadísticas')
  XLSX.writeFile(wb,`${filename}_${new Date().toLocaleDateString('es-MX').replace(/\//g,'-')}.xlsx`)
}

export function exportFormsExcel(forms) {
  const wb=XLSX.utils.book_new()
  const data=[
    ['SISOMA API — Catálogo de Formularios'],
    [`Generado: ${new Date().toLocaleString('es-MX')}`],[],
    ['ID','Nombre','Categoría','Asignado a','Preguntas','Respuestas','Estado','Creado'],
    ...forms.map(f=>[f.id,f.name,f.category,f.assignment,f.questions_count||0,f.responses_count||0,f.status,f.created_at])
  ]
  const ws=XLSX.utils.aoa_to_sheet(data)
  ws['!cols']=[6,40,20,15,10,12,10,12].map(w=>({wch:w}))
  XLSX.utils.book_append_sheet(wb,ws,'Formularios')
  XLSX.writeFile(wb,`SISOMA_Formularios_${new Date().toLocaleDateString('es-MX').replace(/\//g,'-')}.xlsx`)
}
